class RunningAverage:
    def __init__(self):
        self._avg = 0.0
        self._count = 0

    def append(self, value: float) -> None:
        if isinstance(value, torch.Tensor):
            value = value.item()
        self._avg = (value + self._count * self._avg) / (self._count + 1)
        self._count += 1

    @property
    def avg(self) -> float:
        return self._avg

    @property
    def count(self) -> int:
        return self._count

    def reset(self) -> None:
        self._avg = 0.0
        self._count = 0


